43	// §3.3 Autotuner-pickable launch cluster shape. compile.py emits the tuned
44	// cluster shape as three nvcc-safe scalar macros SG_TUNED_CLUSTER_SHAPE_{0,1,2}
45	// plus SG_TUNED_CLUSTER_SHAPE_VOLUME (a single `-Dfoo=2,1,1` is rejected by
46	// nvcc — the driver splits the value on commas). Default 1,1,1 = no cluster,
47	// so the DSMEM helper degrades to a plain block reduce.
48	#ifndef SG_TUNED_CLUSTER_SHAPE_0
49	#define SG_TUNED_CLUSTER_SHAPE_0 1
