55	#define SG_TUNED_CLUSTER_SHAPE_2 1
56	#endif
57	#ifndef SG_TUNED_CLUSTER_SHAPE_VOLUME
58	#define SG_TUNED_CLUSTER_SHAPE_VOLUME \
59	    (SG_TUNED_CLUSTER_SHAPE_0 * SG_TUNED_CLUSTER_SHAPE_1 * SG_TUNED_CLUSTER_SHAPE_2)
60	#endif
