95	void launch_prodigy_step(
96	    std::vector<torch::Tensor>& params,
97	    std::vector<torch::Tensor>& exp_avgs,
98	    std::vector<torch::Tensor>& exp_avg_sqs,
99	    std::vector<torch::Tensor>& s_tracks,
100	    std::vector<torch::Tensor>& param_inits,
101	    std::vector<torch::Tensor>& grads,
102	    torch::Tensor& d_t,
103	    float d_prev,
104	    float beta1, float beta2, float eps, float wd,
105	    float bc1, float bc2
106	) {
107	    // Reduce r, s across all parameters.
108	    auto r_sum = torch::zeros({}, d_t.options());
109	    auto s_sum = torch::zeros({}, d_t.options());
110	#if defined(__HIPCC__)
111	    // LIVE (hipcc): the §5 DPP r/s reduction. The kernel folds d_prev² (r) and
112	    // d_prev² (s) in directly: r = Σ g·(p_init−p)·d_prev², s = Σ d_prev²·|g| —
113	    // numerically identical to the ATen body's two scaled .sum()s. One launch
114	    // per tensor accumulates into a 2-float AGENT accumulator [r,s].
115	    // §5.LAUNCH grid/block: block(256) = 4 wavefronts, grid = min(1024,(n+255)/256).
116	    auto rs_acc = torch::zeros({2}, torch::TensorOptions()
117	                                        .device(d_t.device()).dtype(torch::kFloat32));
118	    auto stream = at::hip::getCurrentHIPStream();
119	    for (size_t i = 0; i < params.size(); i++) {
120	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
121	        auto gf = grads[i].to(torch::kFloat32).contiguous();
122	        auto pf = params[i].to(torch::kFloat32).contiguous();
123	        auto pif = param_inits[i].to(torch::kFloat32).contiguous();
124	        // 64-bit safe element count + grid sizing (Stage 1).
125	        const int64_t n = static_cast<int64_t>(gf.numel());
126	        dim3 block(256), grid(static_cast<unsigned>(
127	            std::min<int64_t>(1024, (n + 255) / 256)));
128	        hipLaunchKernelGGL(native::prodigy_gfx942_rs_reduce, grid, block, 0, stream,
129	                           gf.data_ptr<float>(), pf.data_ptr<float>(),
130	                           pif.data_ptr<float>(),
131	                           rs_acc.data_ptr<float>(), rs_acc.data_ptr<float>() + 1,
132	                           d_prev, n);
133	        SG_HIP_LAUNCH_CHECK(stream);  // mirror sm_90 SG_LAUNCH_CHECK
134	    }
135	    r_sum += rs_acc[0];
136	    s_sum += rs_acc[1];
137	#else
138	    for (size_t i = 0; i < params.size(); i++) {
139	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
140	        auto& p = params[i];
141	        auto& pi = param_inits[i];
142	        auto& g = grads[i];
143	
144	        auto delta = (pi - p).to(torch::kFloat32);
145	        r_sum += (g.to(torch::kFloat32) * delta).sum() * (d_prev * d_prev);
146	        s_sum += (g.to(torch::kFloat32).abs().sum()) * (d_prev * d_prev);
147	    }
148	#endif
149	
150	    // Update d (on-device scalar).
151	    auto candidate = r_sum / (s_sum.abs() + 1e-12f);
152	    d_t.copy_(torch::maximum(d_t.new_full({}, d_prev), candidate));
153	
154	    float d_val = d_t.item<float>();
155	
156	    // Apply Adam with d as effective lr.
157	    for (size_t i = 0; i < params.size(); i++) {
158	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
159	        auto& p = params[i];
160	        auto& g = grads[i];
161	        auto& m = exp_avgs[i];
162	        auto& v = exp_avg_sqs[i];
163	        auto& st = s_tracks[i];
164	
165	        auto g_scaled = d_val * g.to(torch::kFloat32);
166	        prim::ema_update_inplace(m, g_scaled, beta1);
167	        prim::ema_sq_update_inplace(v, g_scaled, beta2);
168	        st.add_(g.to(torch::kFloat32), d_val);
169	        prim::adam_apply_inplace(p, m, v, d_val, bc1, bc2, eps, wd);
170	    }
171	}
