174	void launch_fused_prodigy_step(
175	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq, torch::Tensor s, torch::Tensor param_init, torch::Tensor grad, float lr, float d_lr, float beta1, float beta2, float weight_decay, float eps, float bc1, float bc2
176	) {
177	    auto d_t = torch::tensor({d_lr},
178	        torch::TensorOptions().device(param.device()).dtype(torch::kFloat32));
179	    std::vector<torch::Tensor> vp{param};
180	    std::vector<torch::Tensor> vm{exp_avg};
181	    std::vector<torch::Tensor> vv{exp_avg_sq};
182	    std::vector<torch::Tensor> vs{s};
183	    std::vector<torch::Tensor> vpi{param_init};
184	    std::vector<torch::Tensor> vg{grad};
185	    launch_prodigy_step(vp, vm, vv, vs, vpi, vg,
186	                        d_t, d_lr,
187	                        beta1, beta2, eps, weight_decay, bc1, bc2);
