190	void launch_prodigy_dlr_reduce(
191	    torch::Tensor grad, torch::Tensor param, torch::Tensor param_init, torch::Tensor s, torch::Tensor numerator, torch::Tensor denominator, float eps
192	) {
193	    // numerator += sum(grad * (param - param_init))
194	    auto gf = grad.to(torch::kFloat32);
195	    auto delta = (param - param_init).to(torch::kFloat32);
196	    numerator.add_((gf * delta).sum());
197	    // denominator += sum(|s|)
198	    denominator.add_(s.to(torch::kFloat32).abs().sum());
199	}
