341	// Stage-1 NaN/Inf gradient sanitization (mirror of sm_90 sg_sanitize_grad).
342	// Identity unless built with -DSG_SANITIZE_NONFINITE=1; default byte-identical.
343	// Applied on the APPLY path's grad read only (the r/s reduction is unchanged).
344	#ifndef SG_SANITIZE_NONFINITE
345	#define SG_SANITIZE_NONFINITE 0
346	#endif
347	__device__ __forceinline__ float sg_sanitize_grad(float g) {
348	#if SG_SANITIZE_NONFINITE
349	    return __builtin_isfinite(g) ? g : 0.0f;
350	#else
351	    return g;
352	#endif
353	}
354	static constexpr int kWave = 64;   // == amd::kWave (CDNA3 wavefront width)
355	
356	__device__ __forceinline__ float dabsf(float x) { return __builtin_fabsf(x); }
357	
358	// Block (workgroup) prodigy r/s reduction over `[0..n)`, two AGENT atomics.
359	// r_i = g_i·(p_init_i − p_i)·d_prev² ;  s_i = d_prev²·|g_i|.
360	// blockDim.x must be a multiple of kWave and <= kWave*kWave (<= 4096); LDS holds
361	// one float per wavefront per quantity (<= 2*64 floats).
362	__device__ __forceinline__ void prodigy_rs_block(
363	    const float* __restrict__ g, const float* __restrict__ p,
364	    const float* __restrict__ p_init, float* __restrict__ r_acc,
365	    float* __restrict__ s_acc, float d_prev, int64_t n)
366	{
367	    // LDS/lane bookkeeping is LOCAL to the block (<= 4096 threads) → int. The
368	    // GLOBAL element index/stride is int64 so the reduction cannot wrap (Stage 1).
369	    const int tid    = static_cast<int>(threadIdx.x);
370	    const int lane   = tid % kWave;
371	    const int waveId = tid / kWave;
372	    const int wpb    = static_cast<int>(blockDim.x) / kWave;
373	    const int64_t gtid   = static_cast<int64_t>(blockIdx.x) * blockDim.x + tid;
374	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
375	    const float d2   = d_prev * d_prev;
376	
377	    // VECTORIZED reduction body (WS5/item 6): widen the 3-buffer read to 128-bit
378	    // (f32x4 / dwordx4) memory access — was three scalar loads/iter. The 4 lanes
379	    // accumulate the IDENTICAL scalar partials (r_i = g_i·(p_init_i−p_i)·d_prev²,
380	    // s_i = d²·|g_i|), so the per-thread partials are bit-identical to the scalar
381	    // form — only the access width changes. A scalar TAIL covers the n%4 remainder.
382	    // NONTEMPORAL POLICY: g is the read-once grad → streaming (nontemporal); p is
383	    // the current param (read here, written by the apply → recurring) and p_init
384	    // is re-read every step → both CACHED (keep L2-resident).
385	    using f32x4 = amd::f32x4;
386	    const int64_t n4v = n & ~static_cast<int64_t>(3);   // largest mult of 4 <= n
387	    const auto* g4  = reinterpret_cast<const f32x4*>(g);
388	    const auto* p4  = reinterpret_cast<const f32x4*>(p);
389	    const auto* pi4 = reinterpret_cast<const f32x4*>(p_init);
390	
391	    float r_local = 0.f, s_local = 0.f;
392	    for (int64_t q = gtid; q < (n4v >> 2); q += stride) {
393	        const f32x4 gv  = amd::streaming_load(&g4[q]);   // read-once grad
394	        const f32x4 pv  = amd::cached_load(&p4[q]);      // recurring param (cached)
395	        const f32x4 piv = amd::cached_load(&pi4[q]);     // p_init re-read (cached)
396	        #pragma unroll
397	        for (int l = 0; l < 4; ++l) {
398	            float delta = piv[l] - pv[l];
399	            r_local += gv[l] * delta * d2;
400	            s_local += d2 * dabsf(gv[l]);
401	        }
402	    }
403	    // SCALAR TAIL: the final n%4 elements, identical per-element partials.
404	    for (int64_t i = n4v + gtid; i < n; i += stride) {
405	        float gi = amd::streaming_load(&g[i]);
406	        float delta = amd::cached_load(&p_init[i]) - amd::cached_load(&p[i]);
407	        r_local += gi * delta * d2;
408	        s_local += d2 * dabsf(gi);
409	    }
410	    // two wavefront DPP reduces: every lane holds the wavefront r/s sums.
411	    r_local = amd::wave_reduce_add_dpp(r_local);
412	    s_local = amd::wave_reduce_add_dpp(s_local);
413	
414	    __shared__ float lds_r[kWave];
415	    __shared__ float lds_s[kWave];
416	    if (lane == 0) { lds_r[waveId] = r_local; lds_s[waveId] = s_local; }
417	    amd::workgroup_barrier_release();
418	
419	    // first wavefront reduces both per-wavefront slot arrays, then two atomics.
420	    if (waveId == 0) {
421	        float rs = (lane < wpb) ? lds_r[lane] : 0.f;
422	        float ss = (lane < wpb) ? lds_s[lane] : 0.f;
423	        rs = amd::wave_reduce_add_dpp(rs);
424	        ss = amd::wave_reduce_add_dpp(ss);
425	        if (lane == 0) {
426	            amd::atomic_add_agent_f32(r_acc, rs);
427	            amd::atomic_add_agent_f32(s_acc, ss);
428	        }
429	    }
430	}
431	
432	// Bandwidth-bound reduction → high occupancy (256-thread block = 4 wavefronts;
433	// 8 waves/EU) to hide global-memory latency. (WS5 occupancy wire.)
434	extern "C" SG_KERNEL_BOUNDS(256, 8) void prodigy_gfx942_rs_reduce(
435	    const float* __restrict__ g, const float* __restrict__ p,
436	    const float* __restrict__ p_init, float* __restrict__ r_acc,
437	    float* __restrict__ s_acc, float d_prev, int64_t n)
438	{
439	    prodigy_rs_block(g, p, p_init, r_acc, s_acc, d_prev, n);
440	}
441	
442	// ════════════════════════════════════════════════════════════════════════════
443	// §5.2  Prodigy APPLY — per-element param/state update (elementwise, vectorized
444	// only; NO DPP — the cross-lane r/s reduction is §5 above and stays as-is).
445	//
446	// Once the d-factor d_val = max(d_prev, r/(|s|+1e-12)) is known (host-reduced
447	// from the §5 r/s sums), the apply scales the gradient by d_val and runs the
448	// Adam EMAs + bias-corrected decoupled-weight-decay apply with d_val as the
449	// effective lr, plus the s-track accumulator:
450	//   g_s = d_val·g
451	//   m   = beta1·m + (1-beta1)·g_s ;  v = beta2·v + (1-beta2)·g_s²
452	//   st  = st + d_val·g
453	//   update = (m/bc1)/(sqrt(v/bc2)+eps) ;  p = p - d_val·(update + wd·p)
454	// Math is verbatim from launch_prodigy_step()'s ATen body (ema_update_inplace,
455	// ema_sq_update_inplace, s_track add_, adam_apply_inplace with lr=d_val;
456	// bc1/bc2 un-inverted → divide; sqrtf→__builtin_sqrtf).
457	//
458	// VECTORIZATION (WS5/B — scalar→f32x4): the fp32 path is bandwidth-bound, so the
459	// bulk loop is widened to 128-bit (dwordx4) memory access. grad is read-once via
460	// amd::streaming_load<f32x4>; exp_avg / exp_avg_sq / s_track are vector
461	// load/stored; the param write-once goes through amd::streaming_store<f32x4>.
462	// The 4 lanes each evaluate the IDENTICAL scalar expressions (uniform scalars
463	// d_val/beta1/beta2/bc1/bc2/eps/wd applied to all lanes), so the result is
464	// BIT-IDENTICAL to the scalar path — only the access width changes. A scalar
465	// TAIL handles the final N%4 (and the whole array on the fp32-only fallback).
466	// ════════════════════════════════════════════════════════════════════════════
467	
468	// Per-element Prodigy apply — canonical scalar body, shared by the scalar tail
469	// and (replicated lane-by-lane) the f32x4 fast-path so both are bit-identical.
470	template <typename ParamT, typename GradT>
471	__device__ __forceinline__ void prodigy_apply_elem(
472	    ParamT* __restrict__ param, float* __restrict__ exp_avg,
473	    float* __restrict__ exp_avg_sq, float* __restrict__ s_track,
474	    const GradT* __restrict__ grad, int64_t i, float d_val,
475	    float beta1, float beta2, float eps, float wd, float bc1, float bc2)
476	{
477	    const float g   = sg_sanitize_grad(static_cast<float>(amd::streaming_load(&grad[i])));
478	    const float p   = static_cast<float>(param[i]);
479	    const float g_s = d_val * g;
480	    const float m   = beta1 * exp_avg[i]    + (1.0f - beta1) * g_s;
481	    const float v   = beta2 * exp_avg_sq[i] + (1.0f - beta2) * g_s * g_s;
482	    exp_avg[i]    = m;
483	    exp_avg_sq[i] = v;
484	    s_track[i]    = s_track[i] + d_val * g;
485	    const float update = (m / bc1) / (__builtin_sqrtf(v / bc2) + eps);
486	    amd::streaming_store(&param[i],
487	                         static_cast<ParamT>(p - d_val * (update + wd * p)));
488	}
489	
490	template <typename ParamT, typename GradT>
491	SG_KERNEL_BOUNDS(256, 8) void prodigy_gfx942_apply_kernel(
492	    ParamT* __restrict__ param, float* __restrict__ exp_avg,
493	    float* __restrict__ exp_avg_sq, float* __restrict__ s_track,
494	    const GradT* __restrict__ grad, float d_val,
495	    float beta1, float beta2, float eps, float wd,
496	    float bc1, float bc2, int64_t N)
497	{
498	    // 64-bit grid-stride indexing (Stage 1): cast BEFORE the multiply.
499	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
500	    const int64_t tid    = static_cast<int64_t>(blockIdx.x) * blockDim.x
501	                       + threadIdx.x;
502	
503	    constexpr bool kVecOk =
504	        sizeof(ParamT) == sizeof(float) && sizeof(GradT) == sizeof(float);
505	    const int64_t n4 = kVecOk ? (N >> 2) : 0;   // number of full float4 groups
506	
507	    using f32x4 = amd::f32x4;
508	    auto* p4 = reinterpret_cast<f32x4*>(param);
509	    auto* m4 = reinterpret_cast<f32x4*>(exp_avg);
510	    auto* v4 = reinterpret_cast<f32x4*>(exp_avg_sq);
511	    auto* s4 = reinterpret_cast<f32x4*>(s_track);
512	    const auto* g4 = reinterpret_cast<const f32x4*>(grad);
513	
514	    for (int64_t q = tid; q < n4; q += stride) {
515	        const f32x4 g  = amd::streaming_load(&g4[q]);   // 128-bit dwordx4 load
516	        const f32x4 p  = p4[q];
517	        const f32x4 ea = m4[q];
518	        const f32x4 ev = v4[q];
519	        const f32x4 st = s4[q];
520	        f32x4 mo, vo, so, po;
521	        for (int l = 0; l < 4; ++l) {
522	            const float gl = sg_sanitize_grad(g[l]);  // identity unless sanitize on
523	            const float g_s = d_val * gl;
524	            const float m = beta1 * ea[l] + (1.0f - beta1) * g_s;
525	            const float v = beta2 * ev[l] + (1.0f - beta2) * g_s * g_s;
526	            mo[l] = m;
527	            vo[l] = v;
528	            so[l] = st[l] + d_val * gl;
529	            const float update = (m / bc1) / (__builtin_sqrtf(v / bc2) + eps);
530	            po[l] = p[l] - d_val * (update + wd * p[l]);
531	        }
532	        m4[q] = mo;
533	        v4[q] = vo;
534	        s4[q] = so;
535	        amd::streaming_store(&p4[q], po);               // 128-bit dwordx4 store
536	    }
537	
538	    // SCALAR TAIL: the final N%4 elements (and the whole array on fp32 fallback).
539	    for (int64_t i = (n4 << 2) + tid; i < N; i += stride) {
540	        prodigy_apply_elem(param, exp_avg, exp_avg_sq, s_track, grad, i, d_val,
541	                           beta1, beta2, eps, wd, bc1, bc2);
542	    }
543	}
544	
545	// Force-instantiate the grokking dtype combo (fp32 param + fp32 grad).
546	template __global__ void prodigy_gfx942_apply_kernel<float, float>(
547	    float*, float*, float*, float*, const float*, float,
548	    float, float, float, float, float, float, int64_t);
549	
550	}}} // namespace sg::gfx942::native
551	#endif  // (B) device pass
552	
553	#endif  // GROKKING_KERNELS_GFX942_PRODIGY_GFX942_HIP_HPP_
554

