443	// Multi-tensor fused reduce + step: accumulate d_lr across all tensors,
444	// then apply the Prodigy update to each.
445	void launch_multi_tensor_prodigy_fused_reduce_step(
446	    std::vector<torch::Tensor>& params,
447	    std::vector<torch::Tensor>& grads,
448	    std::vector<torch::Tensor>& param_inits,
449	    std::vector<torch::Tensor>& exp_avgs,
450	    std::vector<torch::Tensor>& exp_avg_sqs,
451	    std::vector<torch::Tensor>& s_bufs,
452	    std::vector<float>& bc1s, std::vector<float>& bc2s,
453	    torch::Tensor d_lr_buf,
454	    float beta1, float beta2, float lr, float wd, float eps
455	) {
456	    if (params.empty()) return;
457	    auto dev = params[0].device();
458	    auto r_partial = torch::zeros({1},
459	        torch::TensorOptions().device(dev).dtype(torch::kFloat32));
460	    auto s_partial = torch::zeros({1},
461	        torch::TensorOptions().device(dev).dtype(torch::kFloat32));
462	    float d_prev = d_lr_buf.item<float>();
463	
464	    auto stream = at::cuda::getCurrentCUDAStream().stream();
465	    const int block = SG_TUNED_BLOCK_SIZE;
466	
467	    for (size_t i = 0; i < params.size(); i++) {
468	        const int64_t N = params[i].numel();
469	        if (N == 0) continue;
470	        const int grid = static_cast<int>(
471	        std::min<int64_t>(65535, (N + block - 1) / block));
472	        AT_DISPATCH_FLOATING_TYPES_AND2(
473	            at::ScalarType::Half, at::ScalarType::BFloat16,
474	            params[i].scalar_type(), "prodigy_mt_reduce", [&] {
475	                prodigy_reduce_kernel<scalar_t, scalar_t>
476	                    <<<grid, block, 0, stream>>>(
477	                    params[i].data_ptr<scalar_t>(),
478	                    param_inits[i].data_ptr<scalar_t>(),
479	                    grads[i].data_ptr<scalar_t>(),
480	                    d_prev,
481	                    r_partial.data_ptr<float>(),
482	                    s_partial.data_ptr<float>(), N);
483	                SG_LAUNCH_CHECK(stream);
484	            });
485	    }
486	
487	    prodigy_update_d_kernel<<<1, 1, 0, stream>>>(
488	        d_lr_buf.data_ptr<float>(),
489	        r_partial.data_ptr<float>(),
490	        s_partial.data_ptr<float>(), d_prev);
491	    SG_LAUNCH_CHECK(stream);
492	
493	    for (size_t i = 0; i < params.size(); i++) {
494	        const int64_t N = params[i].numel();
495	        if (N == 0) continue;
496	        const int grid = static_cast<int>(
497	        std::min<int64_t>(65535, (N + block - 1) / block));
498	        AT_DISPATCH_FLOATING_TYPES_AND2(
499	            at::ScalarType::Half, at::ScalarType::BFloat16,
500	            params[i].scalar_type(), "prodigy_mt_apply", [&] {
501	                prodigy_apply_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
502	                    <<<grid, block, 0, stream>>>(
503	                    params[i].data_ptr<scalar_t>(),
504	                    exp_avgs[i].data_ptr<float>(),
505	                    exp_avg_sqs[i].data_ptr<float>(),
506	                    s_bufs[i].data_ptr<float>(),
507	                    grads[i].data_ptr<scalar_t>(),
508	                    d_lr_buf.data_ptr<float>(),
509	                    beta1, beta2, eps, wd, bc1s[i], bc2s[i], N);
510	                SG_LAUNCH_CHECK(stream);
511	            });
512	    }
513	}
514	
515	}} // namespace sg::sm90
